/* Signature Klingon Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Kahlessa": "From Kahless + -a, in Klingon style: 'little Kahless'.", "Moghvar": "From Mogh + -var.", "Duraq": "From Duras + Q.", "Kortar": "From Kor + tar (warrior?).", "Ghorval": "Built on Klingon phonology: harsh gh, v and l.", "Bek'tar": "Built in Klingon style: bek + 'tar.", "Son of Kahlessa": "Signature lineage-style name.", "House of Moghvar": "Signature house-style name.", "Daughter of Ghorval": "Signature lineage-style name.", "House of Bek'tar": "Signature house-style name."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Kahlessa';
console.log(lookup(q));

